import os
import subprocess
import re
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY', 'changeme-dev-key')

# Diagnostic endpoint for ops team
# Allows running pre-approved network diagnostic commands
APPROVED_COMMANDS = ['ping', 'traceroute', 'dig', 'nslookup', 'curl']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not session.get('authenticated'):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/login', methods=['POST'])
def login():
    # Simple token auth for internal tooling
    token = request.json.get('token', '')
    expected = os.environ.get('AUTH_TOKEN', 'internal-ops-token')
    if token == expected:
        session['authenticated'] = True
        session['user'] = 'ops-engineer'
        return jsonify({'status': 'ok'})
    return jsonify({'error': 'invalid token'}), 403

@app.route('/api/v1/diagnostic', methods=['POST'])
@require_auth
def run_diagnostic():
    """Run network diagnostic command.
    Expected payload: {"command": "ping", "target": "10.0.1.5", "options": "-c 4"}
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'missing payload'}), 400

    command = data.get('command', '').strip()
    target = data.get('target', '').strip()
    options = data.get('options', '').strip()

    # Validate command is in approved list
    if command not in APPROVED_COMMANDS:
        return jsonify({'error': f'command not approved: {command}'}), 403

    # Basic target validation - must look like hostname or IP
    if not re.match(r'^[a-zA-Z0-9._\-]+$', target):
        return jsonify({'error': 'invalid target format'}), 400

    # Build command string
    cmd_str = f"{command} {options} {target}"

    try:
        result = subprocess.run(
            cmd_str,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return jsonify({
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'command timed out'}), 504
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

@app.route('/api/v1/resolve', methods=['POST'])
@require_auth
def resolve_host():
    """Quick DNS resolution helper"""
    data = request.get_json()
    hostname = data.get('hostname', '')
    if not hostname or not re.match(r'^[a-zA-Z0-9._\-]+$', hostname):
        return jsonify({'error': 'invalid hostname'}), 400

    import socket
    try:
        result = socket.getaddrinfo(hostname, None)
        addresses = list(set(addr[4][0] for addr in result))
        return jsonify({'hostname': hostname, 'addresses': addresses})
    except socket.gaierror as e:
        return jsonify({'error': str(e)}), 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
